export function familyKey(item){const kind=offerKind(item).key;const base=normalize(item.name).replace(/\b(ps4|ps5)\b/g,' ').replace(/\b(?:standard|standart|digital|dijital|deluxe|ultimate|premium|gold|special|complete|collector s)(?:\s+(?:edition|surumu|surum|paketi|paket|bundle))?\s*$/g,'').replace(/\b(?:edition|surumu|surum)\s*$/g,'').replace(/\s+/g,' ').replace(/\b(and|ve)\s*$/,'').trim();return (['dlc','upgrade','trial','subscription'].includes(kind)?kind:'base')+':'+base}
